    line = line.strip()
    if not line:
        continue
    if line.startswith('#'):
        continue
    if line.startswith(' - '):
        if current_movie is not None:
            if 'director:' in line:
                director = line.split('director:')[1].strip()
                current_movie['director'] = director
    else:
